const makeId=()=>globalThis.crypto?.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'/',patients:'/patients',schedule:'/schedule',pipeline:'/pipeline',records:'/records',billing:'/billing',analytics:'/analytics',integrations:'/integrations',settings:'/settings',audit:'/audit',admin:'/admin'};
